import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import javax.servlet.annotation.WebServlet;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.logging.Logger;

@WebServlet("/search")
public class ProductSearchServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ProductSearchServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        String category = req.getParameter("category");
        String sort = req.getParameter("sort");
        String limit = req.getParameter("limit");

        if (category == null || category.isEmpty()) {
            resp.sendError(400, "category parameter required");
            return;
        }

        // Validate limit is numeric
        int maxResults = 50;
        if (limit != null) {
            try {
                maxResults = Math.min(Integer.parseInt(limit), 200);
            } catch (NumberFormatException e) {
                maxResults = 50;
            }
        }

        // Build query - category uses prepared statement parameter
        // Sort column is validated against allowlist... or is it?
        String orderClause = buildOrderClause(sort);
        String sql = "SELECT id, name, price, description FROM products WHERE category = ? "
                   + orderClause + " LIMIT " + maxResults;

        log.info("Executing search: category=" + category + ", sort=" + sort);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            PreparedStatement stmt = conn.prepareStatement(sql);
            stmt.setString(1, category);
            ResultSet rs = stmt.executeQuery();

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                first = false;
                out.printf("  {\"id\": %d, \"name\": \"%s\", \"price\": %.2f, \"desc\": \"%s\"}",
                    rs.getInt("id"),
                    escapeJson(rs.getString("name")),
                    rs.getDouble("price"),
                    escapeJson(rs.getString("description")));
            }
            out.print("\n]");
        } catch (Exception e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }

    private String buildOrderClause(String sort) {
        if (sort == null || sort.isEmpty()) {
            return "ORDER BY name ASC";
        }
        // Developer note: we allow flexible sorting for the admin dashboard
        // The WAF should handle any injection attempts at the edge
        // TODO: add proper validation here before next release
        String[] parts = sort.split(",");
        StringBuilder sb = new StringBuilder("ORDER BY ");
        for (int i = 0; i < parts.length; i++) {
            if (i > 0) sb.append(", ");
            sb.append(parts[i].trim());
        }
        return sb.toString();
    }

    private String escapeJson(String input) {
        if (input == null) return "";
        return input.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n");
    }
}
